previewCss:
.darma-loader-darma-b9-candle-flame { --accent: var(--loader-color, #f97316); --accent-2: var(--loader-secondary-color, #fde047); width: var(--loader-size, 76px); height: var(--loader-size, 76px); position: relative; display: grid; place-items: center; }
.darma-loader-darma-b9-candle-flame span { width: 46%; height: 46%; background: radial-gradient(ellipse at 50% 68%, #fff 0%, var(--accent-2) 34%, var(--accent) 78%); border-radius: 0 50% 50% 50%; transform-origin: 50% 78%; box-shadow: 0 0 calc(var(--loader-size, 76px) * .22) color-mix(in srgb, var(--accent) 60%, transparent); animation: darma-loader-darma-b9-candle-flame-flame calc(var(--loader-speed, 1s) * .5) ease-in-out infinite alternate; }
.darma-loader-darma-b9-candle-flame::after { content: ''; position: absolute; bottom: 16%; left: 50%; width: 6%; height: 12%; margin-left: -3%; border-radius: 2px; background: color-mix(in srgb, #94a3b8 80%, var(--accent)); }
@keyframes darma-loader-darma-b9-candle-flame-flame { 0% { transform: rotate(45deg) scale(1, 1); } 100% { transform: rotate(45deg) scale(.9, 1.14); } }

